fn filter_banned(words: &Vec[Str], banned: &Set[Str]) -> Vec[Str] {
  let result = Vec[Str]();
  var i = 0;
  while i < words.len() {
    if !banned.contains(&words[i]) {
      result.push(words[i]);
    }
    i = i + 1;
  }
  return result;
}

fn is_safe(word: Str, banned: &Set[Str]) -> Bool {
  return !banned.contains(&word);
}

fn main() -> Int {
  let banned = Set[Str]();
  banned.insert("bad");
  banned.insert("evil");
  let words = Vec[Str]();
  words.push("hello");
  words.push("bad");
  words.push("world");
  let filtered = filter_banned(&words, &banned);
  return filtered.len();
}
